import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/** Blue/Red in first person (owner, 2026-11-20): the wand is put away and the bare hand shows, moving with the cast. */
@Mixin(FirstPersonHandsAndItemsRenderer.class)
public abstract class BlueRedHandMixin {
    @Shadow protected abstract void renderPlayerArm(PoseStack pose, SubmitNodeCollector buffer, int light, float equipped, float swing, HumanoidArm side, PlayerRenderState state);

    @Inject(method = "submitArmWithItem", at = @At("HEAD"), cancellable = true)
    private void godwand$bareHand(PlayerRenderState state, FirstPersonHandsAndItemsRenderState hands, float partial, float pitch, InteractionHand hand, float swing,
                                  ItemStack stack, float equipped, PoseStack pose, SubmitNodeCollector buffer, int light, CallbackInfo ci) {
        var player = Minecraft.getInstance().player;
        if (hand != InteractionHand.MAIN_HAND || player == null || player.isInvisible() || !net.godwand.client.BlueRedHand.bareHand(player)) return;
        pose.pushPose();
        net.godwand.client.BlueRedHand.firstPerson(pose, player, partial);
        renderPlayerArm(pose, buffer, light, equipped, swing, player.getMainArm(), state);
        pose.popPose();
        ci.cancel();
    }
